def group_anagrams(words):
    groups = {}
    order = []
    for w in words:
        key = ''.join(sorted(w))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(w)
    return [groups[k] for k in order]

def sum_of_first_n_primes(n):
    def isp(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    count = 0
    num = 1
    total = 0
    while count < n:
        num += 1
        if isp(num):
            total += num
            count += 1
    return total

def split_into_runs_by_sign(lst):
    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
    res = []
    for x in lst:
        if res and sign(res[-1][-1]) == sign(x):
            res[-1].append(x)
        else:
            res.append([x])
    return res

def shift_right_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return [fill] * n + lst[:length - n]

def is_alternating_parity_digits(s):
    for i in range(1, len(s)):
        if (int(s[i]) % 2) == (int(s[i - 1]) % 2):
            return False
    return True

