def custom_fibonacci(a, b, n):
    if n == 0:
        return a
    if n == 1:
        return b
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def swap_case_custom(s):
    out = []
    for ch in s:
        if ch.isupper():
            out.append(ch.lower())
        elif ch.islower():
            out.append(ch.upper())
        else:
            out.append(ch)
    return ''.join(out)

def count_trailing_equal(lst):
    if not lst:
        return 0
    last = lst[-1]
    count = 0
    for x in reversed(lst):
        if x == last:
            count += 1
        else:
            break
    return count

def digit_count_base(n, b):
    if n == 0:
        return 1
    count = 0
    while n > 0:
        n //= b
        count += 1
    return count

def remove_adjacent_duplicate_pairs(lst):
    stack = []
    for x in lst:
        if stack and stack[-1] == x:
            stack.pop()
        else:
            stack.append(x)
    return stack

def years_months_days_between(d1, d2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        return [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]
    y1, m1, dd1 = d1
    y2, m2, dd2 = d2
    days = dd2 - dd1
    months = m2 - m1
    years = y2 - y1
    if days < 0:
        pm = m2 - 1
        py = y2
        if pm == 0:
            pm = 12
            py -= 1
        days += dim(py, pm)
        months -= 1
    if months < 0:
        months += 12
        years -= 1
    return (years, months, days)

def char_difference_count(s1, s2):
    if len(s1) != len(s2):
        return -1
    return sum(1 for a, b in zip(s1, s2) if a != b)

def sliding_window_average(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [round(sum(lst[i:i+k]) / k, 4) for i in range(len(lst) - k + 1)]

def zeckendorf_length(n):
    if n == 0:
        return 0
    fibs = [1, 2]
    while fibs[-1] <= n:
        fibs.append(fibs[-1] + fibs[-2])
    fibs.pop()
    count = 0
    remaining = n
    for f in reversed(fibs):
        if f <= remaining:
            remaining -= f
            count += 1
    return count

def nth_lucas_number(n):
    a, b = 2, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def previous_leap_year(year):
    y = year - 1
    while not (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)):
        y -= 1
    return y

def is_valid_username(s):
    if not (3 <= len(s) <= 16):
        return False
    if not s[0].isalpha():
        return False
    return all(c.isalnum() or c == '_' for c in s[1:])

def truncate_column(s, width):
    if len(s) > width:
        return s[:width]
    return s.ljust(width)

def longest_non_increasing_run_length(lst):
    if not lst:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] <= lst[i - 1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def merge_avg_two(d1, d2):
    keys = set(d1) | set(d2)
    res = {}
    for k in keys:
        vals = []
        if k in d1:
            vals.append(d1[k])
        if k in d2:
            vals.append(d2[k])
        res[k] = sum(vals) / len(vals)
    return res

def sliding_window_list(lst, k):
