        return []
    return [lst[i:i+k] for i in range(len(lst) - k + 1)]

def is_permutation_matrix(m):
    n = len(m)
    for row in m:
        if len(row) != n:
            return False
    for row in m:
        if any(v not in (0, 1) for v in row):
            return False
        if sum(row) != 1:
            return False
    for j in range(n):
        if sum(m[i][j] for i in range(n)) != 1:
            return False
    return True

def remove_duplicates_preserve_order(lst):
    seen = []
    result = []
    for x in lst:
        if x not in seen:
            seen.append(x)
            result.append(x)
    return result

def longest_palindromic_substring(s):
    if not s:
        return ""
    best = s[0]
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return s[l+1:r]
    for i in range(len(s)):
        odd = expand(i, i)
        if len(odd) > len(best):
            best = odd
        even = expand(i, i+1)
        if len(even) > len(best):
            best = even
    return best
